brand.extra_css:
/* lime is too light for text on white: text accents use the site's own dark olive (#5d7400); lime stays for fills */
:root { --brand-deep: #4a5c00; --brand-mid: #c8e64d; }
.section-head .kicker, .chapter > header .kicker, .toc .toc-part > .part-row .num { color: #5d7400; }
em { font-style: normal; font-weight: 600; color: #2b3240; }
table.ref { overflow: visible; }
/* addresses, phone numbers and shortcuts read left to right inside Arabic text */
kbd { direction: ltr; unicode-bidi: isolate; }
